<script setup lang="ts">
import { computed } from 'vue'
import { ScaleF } from '../../../../src/framework/draw/types/geometry'
import { qtrc, useLanguage } from '../../../i18n'
import { ICON_CODES } from '../../../actions/uiactiondata'
import type { NotationStyleLike } from './controls.vue'
import { styleDialogImage } from './images'
const props=defineProps<{score?:any;style:NotationStyleLike;goToTextStylePage?:(codeOrIndex:string|number)=>void}>()
useLanguage()
const tr=(s:string)=>qtrc('notation/editstyle/timesignatures',s)
const val=(id:string)=>props.style.value(id)
const bool=(id:string)=>Boolean(val(id))
const set=(id:string,v:unknown)=>props.style.setValue(id,v)
const modify=(id:string,v:unknown)=>props.style.setValue(id,v)
const setScale=(width:number,height:number)=>props.style.setValue(`timeSig${suffix.value}Scale`,new ScaleF(width,height))
function editScale(axis:'width'|'height',event:Event){const input=event.target as HTMLInputElement,s=val(`timeSig${suffix.value}Scale`),old=axis==='width'?s.width():s.height();if(input.value===''||!Number.isFinite(input.valueAsNumber)){input.value=String(old);return}const value=Math.round(Math.max(1,Math.min(999,input.valueAsNumber))*100)/100;input.value=String(value);setScale(axis==='width'||bool(`timeSig${suffix.value}ScaleLock`)?value:s.width(),axis==='height'||bool(`timeSig${suffix.value}ScaleLock`)?value:s.height())}
const styleAndSizeIds=()=>[`timeSig${suffix.value}Style`,`timeSig${suffix.value}Scale`,`timeSig${suffix.value}ScaleLock`,`timeSig${suffix.value}NumDist`,`timeSig${suffix.value}Y`,...(placement.value===1?['timeSigCenterOnBarline']:placement.value===2?['timeSigCenterAcrossStaveGroup']:[])]
const resetStyleAndSize=()=>{for(const id of [...styleAndSizeIds(),...(placement.value===1?['timeSigVSMarginCentered','timeSigVSMarginNonCentered']:[])])props.style.resetValue?.(id)}
const toggle=(id:string)=>set(id,!bool(id))
const placement=computed(()=>Number(val('timeSigPlacement')))
const suffix=computed(()=>placement.value===0?'Normal':placement.value===1?'Above':'Across')
const placements=[['On all staves',0],['Above staves',1],['Across staves',2]] as const
const visibility=[['Show on every system',true],['Hide after the first system where they appear',false]] as const
const repeatOptions=[['changesBeforeBarlineRepeats','At repeats, only show changes before the barline'],['changesBeforeBarlineOtherJumps','At all other jumps, only show changes before the barline']] as const
const courtesy=[['showCourtesiesRepeats','useParensRepeatCourtesies','Show at repeats','repeats-on','repeats-off','repeats-on-parens'],['showCourtesiesOtherJumps','useParensOtherJumpCourtesies','Show at all other jumps','other_jumps-on','other_jumps-off','other_jumps-on-parens'],['showCourtesiesAfterCancellingRepeats','useParensRepeatCourtesiesAfterCancelling','Show when cancelling a courtesy before repeats','cancel_repeat-on','cancel_repeat-off','cancel_repeat-on-parens'],['showCourtesiesAfterCancellingOtherJumps','useParensOtherJumpCourtesiesAfterCancelling','Show when cancelling a courtesy before all other jumps','cancel_other-on','cancel_other-off','cancel_other-on-parens']] as const
</script>
<template>
<div class="sd-column qml-style-page clef-time-page" style="gap:12px">
<fieldset class="sd-groupbox" style="min-width:500px"><legend>{{tr('Clefs')}}</legend><div class="sd-column" style="gap:10px"><div class="sd-column" style="gap:8px"><span class="sd-label">{{tr('Visibility:')}}</span><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="[text,v] in [[ 'Show all clefs on every system',true],['Hide all clefs after the first system where they appear',false]] as const" :key="String(v)" class="sd-radio"><input type="radio" name="clef-visible" :checked="bool('genClef')===v" @change="set('genClef',v)"><span>{{tr(text)}}</span></label></div></div><label class="sd-checkbox" :class="{disabled:!bool('genClef')}"><input type="checkbox" :checked="bool('hideTabClefAfterFirst')" :disabled="!bool('genClef')" @change="toggle('hideTabClefAfterFirst')"><span>{{tr('Hide TAB clefs after the first system where they appear')}}</span></label><label class="sd-checkbox"><input type="checkbox" :checked="bool('genCourtesyClef')" @change="toggle('genCourtesyClef')"><span>{{tr('Show courtesy clefs')}}</span></label><fieldset class="sd-groupbox"><legend>{{tr('Default TAB clef')}}</legend><div class="sd-column" style="gap:8px"><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="[text,v] in [['Standard TAB clef',31],['Serif TAB clef',33]] as const" :key="v" class="sd-radio"><input type="radio" name="tab-clef" :checked="Number(val('tabClef'))===v" @change="set('tabClef',v)"><span>{{tr(text)}}</span></label></div></div></fieldset></div></fieldset>
<fieldset class="sd-groupbox"><legend>{{tr('Time signatures')}}</legend><div class="sd-column" style="gap:8px"><div class="sd-row time-options" style="gap:12px"><div class="sd-column" style="align-self:flex-start;gap:8px"><div class="sd-column" style="gap:8px"><span class="sd-label">{{tr('Position:')}}</span><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="[text,v] in placements" :key="v" class="sd-radio"><input type="radio" name="time-placement" :checked="placement===v" @change="set('timeSigPlacement',v)"><span>{{tr(text)}}</span></label></div><span v-if="placement!==0" class="sd-label">{{tr('Set where time signatures appear using the Layout panel.')}}</span></div></div><div class="sd-image" style="padding:0"><img :src="styleDialogImage(`timeSigImages/timesig-${placement===0?'on_all_staves':placement===1?'above_staves':'across_staves'}.png`)" alt="" style="height:144px"></div></div>
<fieldset class="sd-groupbox"><legend>{{tr('Style and size')}}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:12px"><span class="sd-label" style="width:150px">{{tr('Numeral style:')}}</span><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="[icon,v] in [['𝟑⁄₄',0],['𝟑/₄',1],['3/4',2]] as const" :key="v" class="sd-flat-radio stacked" type="button" role="radio" :aria-checked="Number(val(`timeSig${suffix}Style`))===v" style="width:40px;height:56px;flex:none" @click="set(`timeSig${suffix}Style`,v)"><span class="sd-icon">{{String.fromCodePoint(ICON_CODES[['TIMESIG_STANDARD','TIMESIG_NARROW','TIMESIG_SANSSERIF'][v]])}}</span></button></div><button type="button" class="sd-flat-button icon-only" :disabled="styleAndSizeIds().every(id=>style.isDefault?.(id) === true)" :aria-label="qtrc('global','Reset')" @click="resetStyleAndSize"><span class="sd-icon">{{String.fromCodePoint(ICON_CODES.UNDO)}}</span></button></div>
<div v-if="placement!==0" class="sd-row" style="gap:12px"><span class="sd-label" style="width:150px">{{tr(placement===1?'Alignment with barlines:':'Alignment across staves:')}}</span><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="v in [false,true]" :key="String(v)" class="sd-flat-radio" type="button" role="radio" :aria-checked="bool(placement===1?'timeSigCenterOnBarline':'timeSigCenterAcrossStaveGroup')===v" style="width:28px;height:28px;flex:none" @click="set(placement===1?'timeSigCenterOnBarline':'timeSigCenterAcrossStaveGroup',v)"><span class="sd-icon">{{String.fromCodePoint(ICON_CODES[placement===1?(v?'ALIGN_HORIZONTAL_CENTER':'ALIGN_LEFT'):(v?'ALIGN_VERTICAL_CENTER':'ALIGN_TOP')])}}</span></button></div></div>
<div class="sd-row" style="gap:12px"><span class="sd-label" style="width:150px">{{tr('Scale:')}}</span><div class="sd-row" style="gap:6px"><label class="sd-spinbox" style="width:100px"><span class="sd-icon sd-prefix">{{String.fromCodePoint(ICON_CODES.HORIZONTAL)}}</span><input type="number" min="1" step="0.25" :value="val(`timeSig${suffix}Scale`)?.width?.()??1" @change="editScale('width',$event)"><span class="sd-unit">x</span></label><label class="sd-spinbox" style="width:100px"><span class="sd-icon sd-prefix">{{String.fromCodePoint(ICON_CODES.VERTICAL)}}</span><input type="number" min="1" step="0.25" :value="val(`timeSig${suffix}Scale`)?.height?.()??1" @change="editScale('height',$event)"><span class="sd-unit">x</span></label><button class="sd-flat-button icon-only small" :class="{accent:bool(`timeSig${suffix}ScaleLock`)}" type="button" :aria-pressed="bool(`timeSig${suffix}ScaleLock`)" @click="{const locked=!bool(`timeSig${suffix}ScaleLock`);set(`timeSig${suffix}ScaleLock`,locked);if(locked){const s=val(`timeSig${suffix}Scale`);setScale(s?.width?.()??1,s?.width?.()??1)}}">{{String.fromCodePoint(ICON_CODES[bool(`timeSig${suffix}ScaleLock`)?'LOCK_CLOSED':'LOCK_OPEN'])}}</button></div></div>
<div class="sd-row" style="gap:12px"><span class="sd-label" style="width:150px">{{tr('Gap between numbers (scaled):')}}</span><label class="sd-spinbox" style="width:100px"><input type="number" step="0.1" :value="Number(val(`timeSig${suffix}NumDist`))" @change="set(`timeSig${suffix}NumDist`,Number(($event.target as HTMLInputElement).value))"><span class="sd-unit">sp</span></label></div><div class="sd-row" style="gap:12px" :class="{disabled:placement===2&&bool('timeSigCenterAcrossStaveGroup')}"><span class="sd-label" style="width:150px">{{tr('Vertical placement:')}}</span><label class="sd-spinbox" style="width:100px"><input type="number" step="0.1" :disabled="placement===2&&bool('timeSigCenterAcrossStaveGroup')" :value="Number(val(`timeSig${suffix}Y`))" @change="set(`timeSig${suffix}Y`,Number(($event.target as HTMLInputElement).value))"><span class="sd-unit">sp</span></label></div></div></fieldset>
<label class="sd-checkbox"><input type="checkbox" :checked="bool('genCourtesyTimesig')" @change="toggle('genCourtesyTimesig')"><span>{{tr('Show courtesy time signatures')}}</span></label><fieldset v-if="placement===1" class="sd-groupbox" :disabled="!bool('genCourtesyTimesig')"><legend>{{tr('End-of-staff alignment:')}}</legend><label v-for="[text,v] in [['Hang into page margin',0],['Inset time signature',1],['Inset barline',2]] as const" :key="v" class="sd-radio"><input type="radio" name="timesig-margin" :checked="Number(val(bool('timeSigCenterOnBarline')?'timeSigVSMarginCentered':'timeSigVSMarginNonCentered'))===v" @change="set(bool('timeSigCenterOnBarline')?'timeSigVSMarginCentered':'timeSigVSMarginNonCentered',v)">{{tr(text)}}</label></fieldset></div></fieldset>
<fieldset class="sd-groupbox"><legend>{{tr('Key signatures')}}</legend><div class="sd-column" style="gap:8px"><div class="sd-column" style="gap:8px"><span class="sd-label">{{tr('Visibility:')}}</span><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="[text,v] in visibility" :key="String(v)" class="sd-radio"><input type="radio" name="key-visible" :checked="bool('genKeysig')===v" @change="set('genKeysig',v)"><span>{{tr(text)}}</span></label></div></div><label class="sd-checkbox"><input type="checkbox" :checked="bool('genCourtesyKeysig')" @change="toggle('genCourtesyKeysig')"><span>{{tr('Show courtesy key signatures')}}</span></label><fieldset class="sd-groupbox"><legend>{{qtrc('notation/editstyle/accidentals','When changing to a key signature containing fewer sharps or flats')}}</legend><div class="sd-column" style="gap:6px"><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="[text,v] in [['Don’t show any naturals',0],['Show naturals before the new key signature',1],['Show naturals after the new key signature',2]] as const" :key="v" class="sd-radio"><input type="radio" name="key-naturals" :checked="Number(val('keySigNaturals'))===v" @change="set('keySigNaturals',v)"><span>{{qtrc('notation/editstyle/accidentals',text)}}</span></label></div><label class="sd-checkbox"><input type="checkbox" :checked="bool('keySigShowNaturalsChangingSharpsFlats')" :disabled="Number(val('keySigNaturals'))===0" @change="toggle('keySigShowNaturalsChangingSharpsFlats')"><span>{{tr('Show naturals when switching between sharps and flats')}}</span></label></div></fieldset></div></fieldset>
<fieldset class="sd-groupbox"><legend>{{tr('Clefs, key & time signatures at repeats and jumps')}}</legend><div class="sd-column" style="gap:12px"><fieldset class="sd-groupbox"><legend>{{tr('Changes that apply to both the repeat/jump and the subsequent measure')}}</legend><div class="sd-column" style="gap:8px"><label v-for="[id,text] in repeatOptions" :key="id" class="sd-checkbox"><input type="checkbox" :checked="bool(id)" @change="toggle(id)"><span>{{tr(text)}}</span></label></div></fieldset><fieldset class="sd-groupbox"><legend>{{tr('Changes that apply only after repeats and jumps')}}</legend><div class="sd-column" style="gap:8px"><div class="sd-row" style="gap:12px"><div class="sd-column" style="flex:1;gap:8px"><label class="sd-radio"><input type="radio" name="clef-repeat-place" :checked="bool('placeClefsBeforeRepeats')" @change="set('placeClefsBeforeRepeats',true)"><span>{{tr('Place clefs before repeats')}}</span></label><label class="sd-radio"><input type="radio" name="clef-repeat-place" :checked="!bool('placeClefsBeforeRepeats')" @change="set('placeClefsBeforeRepeats',false)"><span>{{tr('Place clefs after repeats')}}</span></label></div><div class="sd-image" style="padding:0"><img :src="styleDialogImage(`courtesyImages/clefs-${bool('placeClefsBeforeRepeats')?'before':'after'}_repeat.png`)" alt="" style="height:64px"></div></div><div class="sd-row" style="gap:12px"><div style="flex:1"><label class="sd-checkbox"><input type="checkbox" :checked="bool('changesBetweenEndStartRepeat')" @change="toggle('changesBetweenEndStartRepeat')"><span>{{tr('Allow changes between end-start repeats')}}</span></label></div><div class="sd-image" style="padding:0"><img :src="styleDialogImage(`courtesyImages/clefs-${bool('placeClefsBeforeRepeats')?'before':'after'}_repeat-${bool('changesBetweenEndStartRepeat')?'allow':'disallow'}_changes.png`)" alt="" style="height:64px"></div></div></div></fieldset><fieldset class="sd-groupbox"><legend>{{tr('Courtesies')}}</legend><div class="sd-column" style="gap:12px"><div v-for="[show,paren,label,on,off,onParen] in courtesy" :key="show" class="sd-courtesy-grid"><label class="sd-toggle"><input type="checkbox" :checked="bool(show)" @change="toggle(show)"><span class="sd-toggle-track"></span><span>{{tr(label)}}</span></label><div class="sd-image" style="padding:0"><img :src="styleDialogImage(`courtesyImages/${bool(show)?bool(paren)?onParen:on:off}.png`)" alt="" style="height:96px"></div><label class="sd-checkbox" :class="{disabled:!bool(show)}"><input type="checkbox" :checked="bool(paren)" :disabled="!bool(show)" @change="toggle(paren)"><span>{{tr('Use parentheses')}}</span></label></div><label class="sd-checkbox"><input type="checkbox" :checked="bool('smallParens')" @change="toggle('smallParens')"><span>{{qtrc('notation','Small parentheses')}}</span></label></div></fieldset></div></fieldset>
</div>
</template>
